import asyncio
import inspect
from fastapi.dependencies.models import Dependant

class CoroutineCallable:
    async def __call__(self, *args, **kwargs):
        return "hello"

def test_coroutine_class():
    dep = Dependant(call=CoroutineCallable)
    print(f"is_coroutine_callable: {dep.is_coroutine_callable}")
    assert dep.is_coroutine_callable is False

class GeneratorCallable:
    def __call__(self, *args, **kwargs):
        yield "hello"

def test_generator_class():
    dep = Dependant(call=GeneratorCallable)
    print(f"is_gen_callable: {dep.is_gen_callable}")
    assert dep.is_gen_callable is False

class AsyncGeneratorCallable:
    async def __call__(self, *args, **kwargs):
        yield "hello"

def test_async_gen_class():
    dep = Dependant(call=AsyncGeneratorCallable)
    print(f"is_async_gen_callable: {dep.is_async_gen_callable}")
    assert dep.is_async_gen_callable is False

if __name__ == "__main__":
    try:
        test_coroutine_class()
        print("test_coroutine_class passed")
    except AssertionError as e:
        print("test_coroutine_class failed")

    try:
        test_generator_class()
        print("test_generator_class passed")
    except AssertionError as e:
        print("test_generator_class failed")

    try:
        test_async_gen_class()
        print("test_async_gen_class passed")
    except AssertionError as e:
        print("test_async_gen_class failed")

